import{_ as e,C as t,o as i,c as r,a6 as s,E as o}from"./chunks/framework.DycQjAfF.js";const b=JSON.parse('{"title":"Yang Perlu Dikonfirmasi","description":"Daftar pertanyaan dan dokumen yang perlu diminta dari pembimbing magang.","frontmatter":{"title":"Yang Perlu Dikonfirmasi","description":"Daftar pertanyaan dan dokumen yang perlu diminta dari pembimbing magang.","status":"ditinjau","dasar":"hasil penyusunan handbook versi awal","diperbarui":"2026-10-22T00:00:00.000Z","kategori":"Tentang Handbook","kata_kunci":["verifikasi","pertanyaan untuk pembimbing","data yang kurang","belum lengkap","to do"]},"headers":[],"relativePath":"tentang-handbook/perlu-verifikasi.md","filePath":"tentang-handbook/perlu-verifikasi.md"}'),l={name:"tentang-handbook/perlu-verifikasi.md"};function u(g,a,d,k,m,p){const n=t("TabelStatus");return i(),r("div",null,[a[0]||(a[0]=s('<h1 id="yang-perlu-dikonfirmasi" tabindex="-1">Yang Perlu Dikonfirmasi <a class="header-anchor" href="#yang-perlu-dikonfirmasi" aria-label="Permalink to &quot;Yang Perlu Dikonfirmasi&quot;">​</a></h1><p class="lead">Daftar ini bisa dibawa saat bertemu pembimbing. Setelah sebuah poin terjawab, perbarui file terkait dan centang poinnya di versi berikutnya.</p><h2 id="tentang-perusahaan" tabindex="-1">Tentang perusahaan <a class="header-anchor" href="#tentang-perusahaan" aria-label="Permalink to &quot;Tentang perusahaan&quot;">​</a></h2><ul class="daftar-periksa"><li><strong>Visi dan misi resmi</strong> beserta dokumen atau tautan sumbernya.</li><li><strong>Tahun berdiri dan sejarah singkat</strong> BPI.</li><li><strong>Nilai perusahaan.</strong> Apakah <em>Passion, Respect, Integrity, Discipline, Excellent</em> adalah nilai resmi perusahaan atau motto Gudang Teknik?</li><li><strong>Produk utama</strong>: jenis pipa, rentang ukuran, dan standar yang boleh dicantumkan.</li><li><strong>Struktur organisasi</strong> yang boleh ditampilkan, minimal di tingkat departemen.</li><li><strong>Sertifikasi</strong> yang masih berlaku.</li><li><strong>Alamat situs resmi</strong> perusahaan untuk dijadikan sumber utama.</li></ul><h2 id="tentang-gudang-teknik" tabindex="-1">Tentang Gudang Teknik <a class="header-anchor" href="#tentang-gudang-teknik" aria-label="Permalink to &quot;Tentang Gudang Teknik&quot;">​</a></h2><ul class="daftar-periksa"><li>[x] <strong>Denah layout gudang.</strong> Terjawab: denah Blok A lantai 2 dan Blok B lantai 1 (lihat <a href="/WareHouse/alur-kerja/layout-gudang">Layout Gudang</a>).</li><li><strong>Bagian ERP</strong> yang boleh diakses peserta magang.</li><li>[x] <strong>Aturan pengodean barang</strong> resmi. Terjawab: nomor material 9 karakter sesuai standar cataloguing (lihat <a href="/WareHouse/divisi/kode-barang">Kode Barang</a>).</li><li><strong>Parameter stok</strong>: rumus atau cara gudang menetapkan stok minimum, maksimum, ROP, dan safety stock. Instruksi kerja hanya menyebut bahwa level stok ditentukan saat kode stock item dibuat.</li><li><strong>Kategori material yang tidak diminta</strong> sama sekali dalam sebulan.</li><li>[x] <strong>Jadwal stock opname</strong> dan cycle counting. Terjawab: stock opname harian secara bergilir (lihat <a href="/WareHouse/sop/stock-opname">SOP Stock Opname</a>).</li><li><strong>Jadwal kategori barang</strong> yang dihitung setiap hari, dan apakah ada stock opname menyeluruh, misalnya akhir tahun.</li><li>[x] <strong>Siapa yang memesan barang ke vendor.</strong> Terjawab: buyer procurement/purchasing, berdasarkan PR dari Admin Pembuat PR (stock item) atau user (non-stock item).</li><li><strong>Apakah catatan manual di rak sama dengan kartu stok</strong> (<em>stock card</em>) yang disebut di instruksi kerja. Handbook ini menganggap keduanya sama.</li></ul><h2 id="tentang-sop-dan-k3" tabindex="-1">Tentang SOP dan K3 <a class="header-anchor" href="#tentang-sop-dan-k3" aria-label="Permalink to &quot;Tentang SOP dan K3&quot;">​</a></h2><ul class="daftar-periksa"><li>[x] Apakah ada <strong>SOP resmi</strong> untuk penyimpanan, stock opname, dan write off? Terjawab: Kumpulan Instruksi Kerja Gudang Teknik dan prosedur write off QP-4.3.3.</li><li><strong>Nomor dan pengesahan Kumpulan Instruksi Kerja.</strong> Kolom Dibuat/Diperiksa/Disetujui masih kosong, dan beberapa nomor masih tertulis &quot;WI…….&quot; (instruksi kerja penempatan material) atau &quot;xxxxx&quot; (form pengebonan barang sementara).</li><li><strong>Prosedur barang scrap/ex pakai, Prosedur Penjualan Scrap, dan arti &quot;format D2&quot;</strong> yang disebut di prosedur write off.</li><li>Apakah prosedur write off <strong>QP-4.3.3 Rev. 0</strong> (2016) masih revisi terbaru.</li><li>Persetujuan pembimbing untuk <strong>SOP Penerimaan dan Pengeluaran Barang</strong> yang sudah disesuaikan dengan alur kerja.</li><li><strong>APD wajib</strong> di setiap area gudang. Instruksi kerja penempatan material sudah mencantumkan daftar APD, tetapi belum per area.</li><li><strong>Area terbatas</strong> untuk peserta magang.</li><li><strong>Nomor darurat, lokasi APAR dan P3K, jalur evakuasi, dan titik kumpul.</strong></li><li><strong>Aturan limbah</strong> untuk consumable yang bocor atau kedaluwarsa.</li></ul><h2 id="tentang-magang-dan-publikasi" tabindex="-1">Tentang magang dan publikasi <a class="header-anchor" href="#tentang-magang-dan-publikasi" aria-label="Permalink to &quot;Tentang magang dan publikasi&quot;">​</a></h2><ul class="daftar-periksa"><li><strong>Jam dan tempat meeting hari Rabu dan kerja bakti hari Kamis</strong>, serta kegiatan rutin lain jika ada. Isi di <code>docs/data/kegiatan.json</code>.</li><li><strong>Aturan jam kerja, absensi, dan izin</strong> peserta magang.</li><li><strong>Izin penggunaan logo dan warna</strong> perusahaan di website, termasuk file logo resmi dan kode warnanya.</li><li>[x] <strong>Izin publikasi</strong>: apakah website boleh diakses publik, hanya jaringan internal, atau hanya dijalankan lokal.</li><li>[x] <strong>Foto dan screenshot</strong> yang boleh dimuat.</li></ul><h2 id="rekap-status-semua-halaman" tabindex="-1">Rekap status semua halaman <a class="header-anchor" href="#rekap-status-semua-halaman" aria-label="Permalink to &quot;Rekap status semua halaman&quot;">​</a></h2>',11)),o(n,{kolom:"status"})])}const c=e(l,[["render",u]]);export{b as __pageData,c as default};
